import {HM_RULES} from './hm-rules.js';
import {EVENT_PRESETS,PRESET_HINTS,eventPreset} from './event-presets.js';
import {needsQuest} from './event-model.js';
import {verifiedQuestSource} from './quest-runtime.js';
import {QUEST_PRESETS,questPreset,placeQuestPreset} from './quest-presets.js';
import {MAP_WEATHER} from './map-environment.js';
import {completeFieldPreview} from './field-persistence.js';
import {uid,inBounds} from './model.js';
import {authoring,readAuthoring,newScene,completionFlag,prepareScene,sceneIssues,conditionMet,pathDirections,sceneCells,DIRECTIONS,findEvent} from './authoring-model.js';
import {movementAt,wrapDialogue} from './world-model.js';

export const SCENE_ACTIONS={respawn:'Set respawn checkpoint',shake:'Screen shake',weather:'Change weather',rockfall:'Falling rock / object',completeField:'Commit HM puzzle',say:'Dialogue',choice:'Player answer · Yes / No',answers:'Player answers · 2–4 choices',shop:'Open shop',battle:'Trainer battle',giveMon:'Give Pokémon',portrait:'Show Pokémon portrait',if:'Conditional branch',path:'Follow drawn path',face:'Face direction',emote:'Emotion / emote',visible:'Show / hide character',wait:'Wait',flag:'Set / clear flag',set:'Set counter / option',add:'Add / subtract counter',item:'Give / take item',money:'Give / take money',cry:'Pokémon cry',music:'Change music',sound:'Sound effect',fade:'Screen fade',warp:'Go to map',heal:'Heal party',gate:'Open gate',hm:'HM / field action',stop:'Finish scene',abort:'End without completing'};
export function sceneWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={pending:null,draft:null,mapId:null,oldId:null,branch:null,running:false,test:null,stopped:false};
 const data=()=>authoring(api.project()),events=()=>api.project().maps.flatMap(map=>map.markers.filter(n=>n.runtime?.action==='scene').map(n=>({map,n})));
 const options=(rows,value,missing='Choose later…')=>`<option value="">${missing}</option>`+rows.map(([id,name])=>`<option value="${esc(String(id))}" ${String(id)===String(value)?'selected':''}>${esc(name)}</option>`).join('');
 const input=(key,label,value,type='text',extra='')=>`<label>${label}<input data-scene-field="${key}" type="${type}" value="${esc(String(value??''))}" ${extra}></label>`;
 const select=(key,label,rows,value)=>`<label>${label}<select data-scene-field="${key}">${options(rows,value)}</select></label>`;
 const check=(key,label,value)=>`<label class="check"><input data-scene-field="${key}" type="checkbox" ${value?'checked':''}>${label}</label>`;
 const allFlags=()=>api.project().questFlags?.filter(q=>!q.hidden||api.project().maps.some(m=>m.fieldObjects?.some(o=>o.completionFlag===q.id)))||[];
 function open(){const list=events();api.modal('Visual scenes',`<p>Draw where an event starts, then arrange its actions. Incomplete references are highlighted and may be saved as drafts.</p><div class="studio-actions"><button id="sceneNew" type="button" class="primary">＋ Place a scene</button><button id="sceneQuestKits" type="button">Linked quest templates</button><button id="sceneState" type="button">Flags & counters</button><button id="sceneTestState" type="button">Test game state</button></div><div class="field-row"><label>Event template<select id="scenePreset">${Object.entries(EVENT_PRESETS).map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('')}</select></label><button id="sceneUsePreset" type="button">Use template</button></div><p id="scenePresetHint" class="hint-line"></p><label>Find a scene<input id="sceneSearch" type="search" placeholder="Scene, map or dialogue"></label><div id="sceneList"></div>`,null,'Done');const draw=()=>{$('#sceneList').innerHTML=list.filter(({map,n})=>(n.title+' '+map.name+' '+JSON.stringify(n.runtime)).toLowerCase().includes($('#sceneSearch').value.toLowerCase())).map(({map,n})=>{const count=sceneIssues(n,api.project(),map).length;return`<button type="button" class="studio-record ${count?'needs-attention':''}" data-scene="${n.id}"><span><b>${esc(n.title)}</b><small>${esc(map.name)} · ${n.runtime.trigger} · ${n.runtime.steps.length} actions</small></span><small>${count?count+' to finish':'Ready'}</small></button>`;}).join('')||'<p>No matching scenes yet.</p>';document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{const e=list.find(e=>e.n.id===b.dataset.scene);api.loadMap(e.map.id);edit(e.n);});};const hint=()=>{$('#scenePresetHint').textContent=(PRESET_HINTS[$('#scenePreset').value]||'Edit the actions after placing this template.')+' Check native item and trainer selections against your opened ROM.';};$('#scenePreset').onchange=hint;hint();$('#sceneQuestKits').onclick=questKits;$('#sceneUsePreset').onclick=()=>{state.pending={kind:'preset',preset:$('#scenePreset').value};api.close();api.mode('scenePlace');api.collapse();flow();};$('#sceneSearch').oninput=draw;draw();$('#sceneNew').onclick=()=>{state.pending={kind:'place'};api.close();api.mode('scenePlace');api.collapse();flow();};$('#sceneState').onclick=()=>api.hub('state');$('#sceneTestState').onclick=testState;}
 function questKits(){api.modal('Linked quest templates',`<p>Each quest places a linked set of events. Shared milestones are created when you save the complete set. Edit any stage afterwards in Visual scenes.</p><label>Quest<select id="questKit">${Object.entries(QUEST_PRESETS).map(([id,v])=>`<option value="${id}">${esc(v.name)}</option>`).join('')}</select></label><p id="questKitHint"></p><p class="hint-line">These quests remember progress and rewards. Native export requires a compatible save adapter for the opened ROM; drafts and editor previews remain available.</p>`,()=>{const kit=questPreset(api.project(),$('#questKit').value);state.pending={kind:'quest',kit,placements:[]};api.close();api.mode('scenePlace');api.collapse();flow();},'Place quest stages');const hint=()=>{$('#questKitHint').textContent=QUEST_PRESETS[$('#questKit').value].hint;};$('#questKit').onchange=hint;hint();}
 function reviewQuest(p){api.modal('Review '+p.kit.name,`<p>${p.kit.scenes.length} linked events. Shared milestones and one-time rewards are included.</p><ol>${p.kit.scenes.map((n,i)=>{const at=p.placements[i],m=api.project().maps.find(m=>m.id===at.mapId);return`<li>${esc(n.title)} · ${esc(m?.name||'Missing map')} · ${at.x}, ${at.y}</li>`;}).join('')}</ol><p>Open each stage to change dialogue, Pokémon, prerequisites and rewards. Native item IDs must match the target ROM.</p><button id="questRedo" type="button">Place the stages again</button>`,()=>{let placed;api.change(()=>{placed=placeQuestPreset(api.project(),p.kit,p.placements);});api.refresh();api.loadMap(placed[0].mapId);edit(api.map().markers.find(n=>n.id===placed[0].eventId));},'Save linked quest');$('#questRedo').onclick=()=>{p.placements=[];state.pending=p;api.close();api.mode('scenePlace');flow();};}
 function edit(old=null,x=0,y=0,draft=null,mapId=api.map().id){state.draft=draft||structuredClone(old||(state.pending?.kind==='preset'?eventPreset(api.project(),state.pending.preset,x,y):newScene(api.project(),x,y)));state.mapId=mapId;state.oldId=old?.id||null;state.branch=null;editor();}
 function editor(){const n=state.draft,r=n.runtime,map=api.project().maps.find(m=>m.id===state.mapId),issues=sceneIssues(n,api.project(),map),a=data(),session=api.session?.(),saveNotice=needsQuest(n)?session?.reader&&!verifiedQuestSource(session.id)?'This ROM needs a save adapter before this scene can be exported. You can save and preview the draft.':!session?.reader?'Open a ROM to check native saved-quest support.':'' : '';
  api.modal(state.oldId?'Edit visual scene':'Create visual scene',`<div class="studio-actions"><button id="sceneBack" type="button">All scenes</button><button id="sceneTry" type="button">Preview sequence</button></div><label>Name<input id="sceneName" value="${esc(n.title)}" maxlength="120"></label><div id="sceneStatus" class="studio-status ${issues.length?'needs-attention':'ready'}">${issues.length?issues.length+' fields need attention · draft can still be saved':'Ready to test'}</div>${saveNotice?'<p class="callout">'+esc(saveNotice)+'</p>':''}<details class="scene-section" open><summary>Trigger & requirements</summary><div class="field-row"><label>Trigger<select id="sceneTrigger">${[['interact','Interact · face + A'],['step','Step on this tile'],['radius','Enter a radius'],['area','Enter a drawn area'],['enter','Arrive on map · native on new maps'],['portal','Arrive through a portal · preview only']].map(([id,label])=>`<option value="${id}" ${r.trigger===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Repeat<select id="sceneRepeat"><option value="always" ${r.repeat!=='once'?'selected':''}>Repeatable</option><option value="once" ${r.repeat==='once'?'selected':''}>First time + repeat actions</option></select></label></div><label class="check"><input id="sceneEnabled" type="checkbox" ${r.enabled!==false?'checked':''}>Enabled</label>${r.trigger==='radius'?'<label>Radius in tiles<input id="sceneRadius" type="number" min="1" max="8" value="'+(r.radius||2)+'"></label>':''}${r.trigger==='area'?`<button id="sceneDrawArea" type="button">${r.area?'Redraw':'Draw'} trigger area${r.area?' · '+r.area.width+' × '+r.area.height:''}</button>`:''}<label>Count completed interactions<select id="sceneCounter">${options(a.variables.map(v=>[v.id,v.name]),r.counterId,'No counter')}</select></label><div id="sceneConditions"></div><button id="sceneAddCondition" type="button">＋ Add prerequisite</button><label>If prerequisites fail, say (optional)<textarea id="sceneFailText" maxlength="4000">${esc(r.failText||'')}</textarea></label></details><div class="studio-tabs"><button type="button" id="sceneFirst" class="active">${r.repeat==='once'?'First interaction':'Actions'}</button>${r.repeat==='once'?'<button type="button" id="sceneRepeatActions">Subsequent interactions</button>':''}</div><div id="sceneActionList"></div><div class="studio-actions"><select id="sceneActionType" aria-label="Action type">${Object.entries(SCENE_ACTIONS).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select><button type="button" id="sceneAddAction">＋ Add action</button></div>${issues.length?'<details class="scene-section"><summary>Fields to finish</summary><ul>'+issues.map(i=>'<li>'+esc(i.path+': '+i.message)+'</li>').join('')+'</ul></details>':''}${state.oldId?'<div class="studio-actions"><button id="sceneDuplicate" type="button">Duplicate</button><button id="sceneRemove" type="button" class="danger">Remove scene</button></div>':''}`,()=>{collect();save();},'Save draft');
  function collect(){if(!$('#sceneName'))return;n.title=$('#sceneName').value.trim()||'New scene';r.trigger=$('#sceneTrigger').value;r.repeat=$('#sceneRepeat').value;r.enabled=$('#sceneEnabled').checked;r.counterId=$('#sceneCounter').value||null;r.failText=$('#sceneFailText').value;if($('#sceneRadius'))r.radius=Math.max(1,Math.min(8,+$('#sceneRadius').value||2));}
  state.collect=collect;$('#sceneBack').onclick=()=>{collect();api.modal('Leave unsaved scene?',`<p>Save this draft before returning to the scene list.</p><button id="sceneDiscard" type="button">Discard these changes</button>`,()=>{save();open();},'Save & return');$('#sceneDiscard').onclick=open;};$('#sceneTry').onclick=()=>{collect();run(n,{standalone:true}).then(editor);};
  for(const id of ['sceneTrigger','sceneRepeat'])$('#'+id).onchange=()=>{collect();editor();};
  if($('#sceneDrawArea'))$('#sceneDrawArea').onclick=()=>{collect();beginDraw('area');};
  renderConditions($('#sceneConditions'),r.conditions,()=>{collect();editor();});$('#sceneAddCondition').onclick=()=>{collect();r.conditions.push({kind:'flag',flagId:'',value:true});editor();};
  let steps=r.steps;const show=()=>renderActions($('#sceneActionList'),steps,()=>{collect();editor();});$('#sceneFirst').onclick=()=>{collect();steps=r.steps;$('#sceneFirst').classList.add('active');$('#sceneRepeatActions')?.classList.remove('active');show();};if($('#sceneRepeatActions'))$('#sceneRepeatActions').onclick=()=>{collect();steps=r.repeatSteps??=[];$('#sceneRepeatActions').classList.add('active');$('#sceneFirst').classList.remove('active');show();};show();$('#sceneAddAction').onclick=()=>{collect();steps.push(defaultAction($('#sceneActionType').value));show();};
  if($('#sceneDuplicate'))$('#sceneDuplicate').onclick=()=>{collect();const copy=structuredClone(n);copy.id=uid();copy.title+=' copy';delete copy.runtime.completionFlag;delete copy.runtime.areaActiveFlag;copy.x=Math.min(map.width-1,copy.x+1);state.draft=copy;state.oldId=null;editor();};if($('#sceneRemove'))$('#sceneRemove').onclick=()=>{api.change(()=>map.markers=map.markers.filter(v=>v.id!==n.id));api.close();api.refresh();};
 }
 function save(){const n=state.draft,map=api.project().maps.find(m=>m.id===state.mapId);if(!map)throw Error('The scene map is missing.');api.change(()=>{prepareScene(api.project(),n);const old=map.markers.find(v=>v.id===state.oldId);if(old)Object.assign(old,structuredClone(n));else map.markers.push(structuredClone(n));});api.refresh();api.toast(sceneIssues(n,api.project(),map).length?'Draft saved. Highlighted fields can be completed later.':'Scene saved.');}
 function conditionFields(c){const a=data();return select('kind','Requirement',[['flag','Saved flag'],['event','Linked event completed'],['variable','Counter / variable'],['option','Game option'],['badge','Have badge'],['hm','Party knows HM'],['item','Have item'],['money','Have money'],['visited','Visited location']],c.kind)+(c.kind==='flag'?select('flagId','Flag',allFlags().map(q=>[q.id,q.name]),c.flagId)+check('value','Flag is set (unchecked = clear)',c.value!==false):c.kind==='event'?select('eventId','Linked event',events().map(({map,n})=>[n.id,map.name+' / '+n.title]),c.eventId)+check('value','Event completed',c.value!==false):['variable','option'].includes(c.kind)?select('variableId','Counter / option',a.variables.map(v=>[v.id,v.name]),c.variableId)+select('operator','Compare',[['ge','At least'],['eq','Equals'],['gt','Greater than'],['le','At most'],['lt','Less than'],['ne','Not equal']],c.operator||'ge')+input('value','Value',c.value||0,'number','min="0" max="65535"'):c.kind==='badge'?select('badge','Badge',[[1,'Boulder'],[2,'Cascade'],[3,'Thunder'],[4,'Rainbow'],[5,'Soul'],[6,'Marsh'],[7,'Volcano'],[8,'Earth']],c.badge):c.kind==='hm'?select('hm','HM',['cut','fly','surf','strength','flash','rocksmash','waterfall','dive'].map(x=>[x,x.toUpperCase()]),c.hm):c.kind==='item'?select('itemRef','Custom item',a.items.map(i=>[i.id,i.name]),c.itemRef)+input('itemId','Or native item ID',c.itemId||13,'number','min="1" max="4095"')+input('quantity','Quantity',c.quantity||1,'number','min="1" max="999"'):c.kind==='visited'?select('mapId','Location',api.project().maps.map(m=>[m.id,m.name]),c.mapId)+check('value','Has visited',c.value!==false):input('amount','Money',c.amount||100,'number','min="0" max="999999"'));}
 function readFields(target,value){target.querySelectorAll('[data-scene-field]').forEach(el=>{const key=el.dataset.sceneField;value[key]=el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value;});}
 function renderConditions(target,conditions,refresh){target.innerHTML=conditions.map((c,i)=>`<article class="scene-condition"><b>Prerequisite ${i+1}</b><div data-condition-fields="${i}">${conditionFields(c)}</div><button data-condition-remove="${i}" type="button">Remove prerequisite</button></article>`).join('');target.querySelectorAll('[data-condition-fields]').forEach(el=>{el.querySelectorAll('input,select').forEach(input=>input.onchange=()=>{readFields(el,conditions[+el.dataset.conditionFields]);refresh();});});target.querySelectorAll('[data-condition-remove]').forEach(b=>b.onclick=()=>{conditions.splice(+b.dataset.conditionRemove,1);refresh();});}
 function defaultAction(type){return{id:uid(),type,...(type==='respawn'?{healId:1}:type==='shake'?{x:2,y:2,count:8,interval:4}:type==='weather'?{weather:3}:type==='rockfall'?{actorId:'',x:0,y:4,height:3}:type==='completeField'?{targetId:''}:type==='say'?{text:'New dialogue',fit:true,scroll:false}:type==='answers'?{text:'What would you like?',allowCancel:true,cancel:[],choices:[{id:uid(),label:'First answer',steps:[]},{id:uid(),label:'Second answer',steps:[]}]}:type==='shop'?{items:[13]}:type==='battle'?{trainerId:1,intro:'Let us battle!',defeat:'You won!'}:type==='giveMon'?{species:25,level:5,itemId:0}:type==='portrait'?{species:25}:type==='choice'?{text:'Will you help?',yes:[{id:uid(),type:'say',text:'Thank you!'}],no:[{id:uid(),type:'say',text:'Maybe another time.'}]}:type==='if'?{conditions:[],then:[],else:[]}:type==='path'?{actorId:'player',points:[],speed:'walk',wait:true}:type==='face'?{actorId:'self',direction:'down'}:type==='emote'?{actorId:'self',emotion:'exclaim',direction:'down'}:type==='visible'?{actorId:'self',visible:true}:type==='wait'?{frames:60}:['set','add'].includes(type)?{variableId:'',value:type==='add'?1:0}:type==='flag'?{flagId:'',value:true}:type==='item'?{itemRef:'',itemId:13,quantity:1,operation:'give'}:type==='money'?{amount:100,operation:'give'}:type==='cry'?{species:25,wait:true}:type==='music'?{trackId:'',songId:0}:type==='sound'?{soundId:5,wait:true}:type==='fade'?{mode:0}:type==='warp'?{to:null}:type==='hm'?{effect:'flash',requireHM:true}:type==='gate'?{gateId:''}:{})};}
 function renderActions(target,steps,refresh){const status=$('#sceneStatus');if(status&&state.draft){const issues=sceneIssues(state.draft,api.project(),api.project().maps.find(m=>m.id===state.mapId));status.className='studio-status '+(issues.length?'needs-attention':'ready');status.textContent=issues.length?issues.length+' fields need attention · draft can still be saved':'Ready to test';}target.innerHTML=steps.map((s,i)=>`<article class="scene-action"><b>${i+1}. ${esc(SCENE_ACTIONS[s.type]||s.type)}</b><p>${esc(actionSummary(s))}</p><div class="studio-actions"><button type="button" data-action-edit="${i}">Edit</button><button type="button" data-action-up="${i}" ${i?'':'disabled'} aria-label="Move action earlier">↑</button><button type="button" data-action-down="${i}" ${i<steps.length-1?'':'disabled'} aria-label="Move action later">↓</button><button type="button" data-action-remove="${i}" aria-label="Remove action">×</button></div></article>`).join('')||'<p class="hint-line">No actions in this branch.</p>';target.querySelectorAll('[data-action-edit]').forEach(b=>b.onclick=()=>{state.collect?.();editAction(steps[+b.dataset.actionEdit],refresh);});for(const [attribute,delta]of [['actionUp',-1],['actionDown',1]])target.querySelectorAll('[data-'+attribute.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+']').forEach(b=>b.onclick=()=>{const i=+b.dataset[attribute];[steps[i],steps[i+delta]]=[steps[i+delta],steps[i]];renderActions(target,steps,refresh);});target.querySelectorAll('[data-action-remove]').forEach(b=>b.onclick=()=>{steps.splice(+b.dataset.actionRemove,1);renderActions(target,steps,refresh);});}
 function actionSummary(s){return ['say','choice','answers'].includes(s.type)?s.dialogueId?'Linked dialogue':s.text||'Write dialogue':s.type==='path'?(s.points?.length||0)+' points · '+s.speed:['set','add'].includes(s.type)?(data().variables.find(v=>v.id===s.variableId)?.name||'Choose counter')+' · '+s.value:s.type==='if'?(s.conditions?.length||0)+' conditions · '+(s.then?.length||0)+' / '+(s.else?.length||0)+' actions':s.type==='item'?s.operation+' '+s.quantity+' × '+(data().items.find(i=>i.id===s.itemRef)?.name||'item '+s.itemId):s.type==='music'?data().music.find(t=>t.id===s.trackId)?.name||'Native track '+s.songId:s.type==='wait'?s.frames+' frames':s.direction||s.emotion||'';}
 function actorOptions(){const map=api.project().maps.find(m=>m.id===state.mapId);return[['player','Player'],['self','This event’s character'],...map.markers.filter(n=>n.npc||n.rom?.type==='npc').map(n=>[n.id,n.title])];}
 function editAction(s,back=editor){const a=data();let body='';
  if(['say','choice','answers'].includes(s.type))body=`<label>Dialogue<textarea data-scene-field="text" maxlength="8000">${esc(s.text||'')}</textarea></label>`+select('dialogueId','Or reusable dialogue',a.dialogues.map(d=>[d.id,d.name]),s.dialogueId)+check('scroll','Scroll text automatically',s.scroll)+check('fit','Fit text into native text-box pages',s.fit!==false)+(s.type==='choice'?'<div class="studio-actions"><button id="sceneEditYes" type="button">Yes actions</button><button id="sceneEditNo" type="button">No / cancel actions</button></div>':'');
  else if(s.type==='if')body='<div id="branchRequirements"></div><button id="branchAddRequirement" type="button">＋ Add requirement</button><div class="studio-actions"><button id="sceneEditThen" type="button">Conditions met</button><button id="sceneEditElse" type="button">Otherwise</button></div>';
  else if(['path','face','emote','visible'].includes(s.type)){body=select('actorId','Character',actorOptions(),s.actorId);if(s.type==='path')body+='<button id="sceneDrawPath" type="button">Draw / edit path on map</button><p class="hint-line">Place the first point at the character’s starting tile. Native movement follows this route relative to the character’s position when triggered.</p>'+select('speed','Movement',[['walk','Walk'],['run','Fast walk']],s.speed||'walk')+check('wait','Wait until path completes',s.wait!==false);if(s.type==='face'||s.type==='emote')body+=select('direction','Facing',Object.keys(DIRECTIONS).map(d=>[d,d]),s.direction||'down');if(s.type==='emote')body+=select('emotion','Emotion',[['exclaim','Exclamation'],['question','Question'],['happy','Smile'],['shock','Shock · exclaim + jump'],['fear','Fear · exclaim + jump + step back']],s.emotion);if(s.type==='visible')body+=check('visible','Character visible',s.visible!==false);}
  else if(s.type==='wait')body=input('frames','Wait in frames (60 ≈ 1 second)',s.frames,'number','min="1" max="36000"');
  else if(s.type==='flag')body=select('flagId','Saved flag',allFlags().map(q=>[q.id,q.name]),s.flagId)+check('value','Set (unchecked = clear)',s.value!==false);
  else if(['set','add'].includes(s.type))body=select('variableId','Counter / option',a.variables.map(v=>[v.id,v.name]),s.variableId)+input('value',s.type==='add'?'Amount (negative subtracts)':'Value',s.value,'number','min="-65535" max="65535"');
  else if(s.type==='item')body=select('operation','Action',[['give','Give'],['take','Take']],s.operation)+select('itemRef','Custom item',a.items.map(i=>[i.id,i.name]),s.itemRef)+input('itemId','Or native item ID',s.itemId||13,'number','min="1" max="4095"')+input('quantity','Quantity',s.quantity||1,'number','min="1" max="999"');
  else if(s.type==='money')body=select('operation','Action',[['give','Give'],['take','Take']],s.operation)+input('amount','Amount',s.amount,'number','min="0" max="999999"');
  else if(s.type==='shop')body='<label>Native item IDs (comma separated)<input id="sceneShopItems" value="'+(s.items||[]).filter(i=>typeof i==='number').join(', ')+'"></label>'+a.items.map(i=>'<label class="check"><input type="checkbox" data-shop-custom="'+i.id+'" '+(s.items?.includes(i.id)?'checked':'')+'>'+esc(i.name)+'</label>').join('');
  else if(s.type==='battle')body=input('trainerId','Native trainer ID',s.trainerId,'number','min="1" max="4095"')+input('intro','Battle introduction',s.intro)+input('defeat','Defeat dialogue',s.defeat);
  else if(s.type==='giveMon')body=input('species','Native species ID',s.species,'number','min="1"')+input('level','Level',s.level,'number','min="1" max="100"')+input('itemId','Held item ID (0 = none)',s.itemId||0,'number','min="0"');
  else if(s.type==='portrait')body=input('species','Native species ID',s.species,'number','min="1"');
  else if(s.type==='cry')body=input('species','Native Pokémon species ID',s.species,'number','min="1" max="8191"')+check('wait','Wait for cry to finish',s.wait!==false);
  else if(s.type==='music')body=select('trackId','Imported track',a.music.map(t=>[t.id,t.name]),s.trackId)+input('songId','Or native song ID',s.songId||0,'number','min="0" max="65535"');
  else if(s.type==='sound')body=input('soundId','Native sound effect ID',s.soundId||5,'number','min="0" max="1023"')+check('wait','Wait for sound',s.wait!==false);
  else if(s.type==='shake')body=input('x','Horizontal strength',s.x,'number','min="0" max="16"')+input('y','Vertical strength',s.y,'number','min="0" max="16"')+input('count','Shake count (even)',s.count,'number','min="2" max="100" step="2"')+input('interval','Frames per shake',s.interval,'number','min="1" max="60"');
  else if(s.type==='respawn')body=input('healId','Healing checkpoint number',s.healId,'number','min="1" max="20"')+'<p>Uses the source healing table. The region builder assigns these entries in new-game mode.</p>';
  else if(s.type==='weather')body=select('weather','Weather',MAP_WEATHER,s.weather);
  else if(s.type==='rockfall')body=select('actorId','Rock NPC',[...actorOptions().filter(([id])=>!['player','self'].includes(id)),...(api.map().fieldObjects||[]).filter(o=>o.kind!=='cut').map(o=>[o.id,o.name])],s.actorId)+input('x','Landing X',s.x,'number','min="0"')+input('y','Landing Y',s.y,'number','min="1"')+input('height','Fall height in tiles',s.height,'number','min="1" max="8"')+'<p>Place a rock NPC above the landing. This uses native object movement; add a shake and impact sound after landing. Artwork and movement must fit the route.</p>';
  else if(s.type==='completeField')body=select('targetId','Permanent HM object',(api.map().fieldObjects||[]).filter(o=>o.permanent).map(o=>[o.id,o.name]),s.targetId)+'<p>Run this only in the solved branch of your puzzle. Strength restores the configured solved tile after re-entry and saving.</p>';
  else if(s.type==='fade')body=select('mode','Fade',[[0,'To black'],[1,'From black'],[2,'To white'],[3,'From white']],s.mode||0);
  else if(s.type==='warp')body='<p>'+esc(s.to?(api.project().maps.find(m=>m.id===s.to.mapId)?.name||'Missing map')+' · '+s.to.x+', '+s.to.y:'Choose where the player arrives.')+'</p><label>Destination map<select id="sceneWarpMap">'+options(api.project().maps.map(m=>[m.id,m.name]),s.to?.mapId||state.mapId)+'</select></label><button id="scenePickArrival" type="button">Pick exact arrival tile</button>';
  else if(s.type==='gate')body=select('gateId','Gate',(api.project().maps.find(m=>m.id===state.mapId).gates||[]).map(g=>[g.id,g.name]),s.gateId);
  else if(s.type==='hm')body=select('effect','HM',[['flash','Flash'],['strength','Strength'],['cut','Cut'],['rocksmash','Rock Smash']],s.effect)+check('requireHM','Require HM and badge',s.requireHM!==false)+select('targetId','Rock / tree',(api.map().fieldObjects||[]).map(o=>[o.id,o.name]),s.targetId);
  else body='<p>'+esc(SCENE_ACTIONS[s.type])+'.</p>';
  if(s.type==='answers')body+=check('allowCancel','Allow B / cancel',s.allowCancel!==false)+'<div id="answerBranches"></div>';
  const collectAction=()=>{readFields($('#dialogBody'),s);if(s.type==='weather')s.weather=+s.weather;if(s.type==='shop')s.items=[$('#sceneShopItems').value.split(',').map(v=>+v.trim()).filter(Boolean),[...document.querySelectorAll('[data-shop-custom]:checked')].map(el=>el.dataset.shopCustom)].flat();if(s.type==='answers')document.querySelectorAll('[data-answer-label]').forEach(el=>s.choices[+el.dataset.answerLabel].label=el.value);};
  api.modal(SCENE_ACTIONS[s.type]||'Action',body,()=>{collectAction();back();return false;},'Done');
  if(s.type==='answers'){const box=$('#answerBranches');box.innerHTML=s.choices.map((c,i)=>'<article class="scene-action"><label>Answer '+(i+1)+'<input data-answer-label="'+i+'" maxlength="24" value="'+esc(c.label)+'"></label><button type="button" data-answer-branch="'+i+'">Edit answer actions</button>'+(s.choices.length>2?'<button type="button" data-answer-remove="'+i+'">Remove answer</button>':'')+'</article>').join('')+(s.choices.length<4?'<button id="sceneAddAnswer" type="button">＋ Add answer</button>':'')+'<button id="sceneAnswerCancel" type="button">Cancel actions</button>';box.querySelectorAll('[data-answer-branch]').forEach(b=>b.onclick=()=>{collectAction();editBranch(s.choices[+b.dataset.answerBranch].steps,()=>editAction(s,back));});box.querySelectorAll('[data-answer-remove]').forEach(b=>b.onclick=()=>{collectAction();s.choices.splice(+b.dataset.answerRemove,1);editAction(s,back);});if($('#sceneAddAnswer'))$('#sceneAddAnswer').onclick=()=>{collectAction();s.choices.push({id:uid(),label:'New answer',steps:[]});editAction(s,back);};$('#sceneAnswerCancel').onclick=()=>{collectAction();editBranch(s.cancel??=[],()=>editAction(s,back));};}
  for(const [id,key]of [['sceneEditYes','yes'],['sceneEditNo','no'],['sceneEditThen','then'],['sceneEditElse','else']])if($('#'+id))$('#'+id).onclick=()=>{readFields($('#dialogBody'),s);editBranch(s[key]??=[],()=>editAction(s,back));};
  if(s.type==='if'){renderConditions($('#branchRequirements'),s.conditions??=[],()=>editAction(s,back));$('#branchAddRequirement').onclick=()=>{s.conditions.push({kind:'flag',flagId:'',value:true});editAction(s,back);};}
  if($('#sceneDrawPath'))$('#sceneDrawPath').onclick=()=>{readFields($('#dialogBody'),s);beginDraw('path',s);};
  if($('#scenePickArrival'))$('#scenePickArrival').onclick=()=>{const target=$('#sceneWarpMap').value;if(!target)throw Error('Choose an arrival map.');state.pending={kind:'warp',step:s,mapId:state.mapId};api.close();api.loadMap(target);api.mode('sceneWarp');flow();};
 }
 function editBranch(steps,back){api.modal('Branch actions','<div id="branchActions"></div><div class="studio-actions"><select id="branchActionType">'+Object.entries(SCENE_ACTIONS).map(([id,name])=>'<option value="'+id+'">'+name+'</option>').join('')+'</select><button id="branchAddAction" type="button">＋ Add action</button></div>',()=>{back();return false;},'Back');renderActions($('#branchActions'),steps,()=>editBranch(steps,back));$('#branchAddAction').onclick=()=>{steps.push(defaultAction($('#branchActionType').value));editBranch(steps,back);};}
 function beginDraw(kind,step=null){state.pending={kind,step,points:step?.points?structuredClone(step.points):[],mapId:state.mapId};api.close();api.loadMap(state.mapId);api.mode(kind==='area'?'sceneArea':'scenePath');api.collapse();flow();api.draw();}
 function flow(){const el=$('#sceneFlow');if(!el)return;const p=state.pending;el.hidden=!p;if(!p){el.innerHTML='';return;}if(p.kind==='quest'){const n=p.kit.scenes[p.placements.length];el.innerHTML=`<div><b>${esc(n.title)} · ${p.placements.length+1} / ${p.kit.scenes.length}</b><span>Tap a free tile. Change maps here to spread stages across the world.</span><select id="questPlaceMap" aria-label="Map for quest stage">${api.project().maps.map(m=>`<option value="${esc(m.id)}" ${api.map().id===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="flow-actions"><button id="questPlaceUndo" type="button" ${p.placements.length?'':'disabled'}>Back</button><button id="questPlaceCancel" type="button">Cancel quest</button></div>`;$('#questPlaceMap').onchange=()=>{api.loadMap($('#questPlaceMap').value);flow();};$('#questPlaceUndo').onclick=()=>{p.placements.pop();flow();};$('#questPlaceCancel').onclick=()=>{state.pending=null;flow();api.mode('move');};return;}el.innerHTML=`<div><b>${['place','preset'].includes(p.kind)?'Tap a scene trigger tile':p.kind==='area'?'Drag a trigger area':p.kind==='warp'?'Tap the exact arrival tile':'Tap points or drag a character path'}</b><span>${p.kind==='path'?(p.points?.length||0)+' points · starts at the first marked tile':'Two fingers still pan and zoom'}</span></div><div class="flow-actions">${p.kind==='path'?'<button id="scenePathClear" type="button">Clear</button><button id="sceneDrawDone" type="button" class="primary">Done</button>':''}<button id="sceneDrawCancel" type="button" aria-label="Cancel drawing">×</button></div>`;$('#sceneDrawCancel').onclick=()=>{state.pending=null;flow();api.mode('move');if(state.draft)editor();};if($('#scenePathClear'))$('#scenePathClear').onclick=()=>{p.points=[];flow();api.draw();};if($('#sceneDrawDone'))$('#sceneDrawDone').onclick=()=>{if(p.points.length<2){api.toast('Draw at least two points.');return;}p.step.points=structuredClone(p.points);state.pending=null;flow();api.mode('move');editor();};}
 function tap(x,y){const p=state.pending;if(!p||!inBounds(api.map(),x,y))return;if(p.kind==='quest'){const map=api.map();if(movementAt(map,x,y).collision||map.markers.some(n=>n.x===x&&n.y===y&&n.runtime)||p.placements.some(at=>at.mapId===map.id&&at.x===x&&at.y===y)||api.project().links?.some(l=>l.runtime?.type==='portal'&&[l.from,l.to].some(at=>at?.mapId===map.id&&at.x===x&&at.y===y))){api.toast('Choose a free walkable tile beside any doors or portals.');return;}p.placements.push({mapId:map.id,x,y});if(p.placements.length===p.kit.scenes.length){state.pending=null;flow();api.mode('move');reviewQuest(p);}else flow();return;}if(p.kind==='place'||p.kind==='preset'){const draft=p.kind==='preset'?eventPreset(api.project(),p.preset,x,y):null;state.pending=null;flow();api.mode('move');edit(null,x,y,draft);if(state.newSettings){state.newSettings=false;state.draft.title='Game settings';state.draft.runtime.steps=api.settingsActions();editor();}}else if(p.kind==='warp'){p.step.to={mapId:api.map().id,x,y};state.pending=null;flow();api.loadMap(p.mapId);api.mode('move');editor();}else if(p.kind==='path'){const prev=p.points.at(-1);if(!prev||prev.x!==x||prev.y!==y)p.points.push({x,y});if(p.points.length>257)p.points.pop();flow();api.draw();}}
 function start(t,g){g.kind='sceneDraw';g.startTile=t;g.lastTile=t;if(state.pending?.kind==='path')tap(t.x,t.y);}
 function move(t,g){if(!state.pending||!inBounds(api.map(),t.x,t.y))return;g.lastTile=t;if(state.pending.kind==='path')tap(t.x,t.y);api.draw();}
 function finish(g){if(state.pending?.kind==='area'){const a=g.startTile,b=g.lastTile;if(!inBounds(api.map(),a.x,a.y)||!inBounds(api.map(),b.x,b.y))return;state.draft.runtime.area={x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),width:Math.abs(a.x-b.x)+1,height:Math.abs(a.y-b.y)+1};state.pending=null;flow();api.mode('move');editor();}}
 function draw(c,map,scale){const p=state.pending;if(p?.kind==='path'&&p.points.length){c.save();c.strokeStyle='#f6d364';c.lineWidth=3/scale;c.beginPath();for(const[i,point]of p.points.entries())c[i?'lineTo':'moveTo']((point.x+.5)*16,(point.y+.5)*16);c.stroke();c.fillStyle='#f6d364';for(const point of p.points){c.beginPath();c.arc((point.x+.5)*16,(point.y+.5)*16,4/scale,0,Math.PI*2);c.fill();}c.restore();}if(p?.kind==='area'&&api.gesture()){const g=api.gesture(),a=g.startTile,b=g.lastTile;if(a&&b){c.fillStyle='#e9c26655';c.fillRect(Math.min(a.x,b.x)*16,Math.min(a.y,b.y)*16,(Math.abs(a.x-b.x)+1)*16,(Math.abs(a.y-b.y)+1)*16);}}}
 function testState(){
  const p=api.world().state.play||state.test||{quests:new Set(),variables:new Map(),bag:new Map(),hmBadges:new Set(),hmMoves:new Set(),actorPositions:new Map(),money:0};state.test=p;p.quests??=new Set();p.bag??=new Map();const a=data(),sceneRows=events().filter(({n})=>n.runtime?.completionFlag),bagRows=new Map();
  for(const [effect,h]of Object.entries(HM_RULES))bagRows.set('native:'+h.hmItem,{key:h.hmItem,name:h.name+' HM'});
  for(const item of a.items)bagRows.set('custom:'+item.id,{key:item.id,name:item.name});
  for(const [effect,r]of Object.entries(api.project().hmRules?.moves||{}))if(r.mode==='item'&&!r.itemRef)bagRows.set('native:'+r.itemId,{key:r.itemId,name:HM_RULES[effect].name+' tool · item '+r.itemId});
  api.modal('Test game state',`<p>These switches affect editor previews only.</p><details open><summary>Badges & taught moves</summary>${Array.from({length:8},(_,i)=>`<label class="check"><input data-test-badge="${i+1}" type="checkbox" ${p.hmBadges?.has(i+1)?'checked':''}>Badge ${i+1}</label>`).join('')}${Object.entries(HM_RULES).map(([id,h])=>`<label class="check"><input data-test-hm="${id}" type="checkbox" ${p.hmMoves?.has(id)?'checked':''}>Party knows ${h.name}</label>`).join('')}</details><details><summary>Bag — HMs & replacement tools</summary>${[...bagRows].map(([id,item])=>`<label>${esc(item.name)}<input data-test-bag="${esc(id)}" type="number" min="0" max="999" value="${p.bag.get(item.key)||0}"></label>`).join('')}<label>Another native item ID<input id="testNativeItem" type="number" min="1" max="65535" placeholder="Optional"></label><label>Quantity<input id="testNativeQuantity" type="number" min="0" max="999" value="1"></label></details><details><summary>Completed events</summary>${sceneRows.map(({map,n})=>`<label class="check"><input data-test-event="${n.id}" type="checkbox" ${p.quests.has(n.runtime.completionFlag)?'checked':''}>${esc(map.name+' / '+n.title)}</label>`).join('')||'<p>No scenes with saved completion state yet.</p>'}</details><details><summary>Flags</summary>${allFlags().map(q=>`<label class="check"><input data-test-flag="${q.id}" type="checkbox" ${p.quests.has(q.id)?'checked':''}>${esc(q.name)}</label>`).join('')}</details><details><summary>Counters & options</summary>${a.variables.map(v=>`<label>${esc(v.name)}<input data-test-var="${v.id}" type="number" min="0" max="${2**v.bits-1}" value="${p.variables?.get(v.id)||0}"></label>`).join('')}</details>`,()=>{
   const itemText=$('#testNativeItem').value,id=+itemText,quantity=+$('#testNativeQuantity').value;if(itemText&&(!Number.isInteger(id)||id<1||id>65535||!Number.isInteger(quantity)||quantity<0||quantity>999))throw Error('Choose a valid test item and quantity.');
   const entries=[...document.querySelectorAll('[data-test-bag]')].map(e=>[bagRows.get(e.dataset.testBag).key,+e.value]);if(entries.some(([,n])=>!Number.isInteger(n)||n<0||n>999))throw Error('Test bag quantities are whole numbers from 0 to 999.');
   p.hmBadges=new Set([...document.querySelectorAll('[data-test-badge]:checked')].map(e=>+e.dataset.testBadge));p.hmMoves=new Set([...document.querySelectorAll('[data-test-hm]:checked')].map(e=>e.dataset.testHm));for(const q of allFlags())p.quests.delete(q.id);document.querySelectorAll('[data-test-flag]:checked').forEach(e=>p.quests.add(e.dataset.testFlag));for(const {n}of sceneRows)p.quests.delete(n.runtime.completionFlag);document.querySelectorAll('[data-test-event]:checked').forEach(e=>p.quests.add(sceneRows.find(({n})=>n.id===e.dataset.testEvent).n.runtime.completionFlag));p.variables??=new Map();document.querySelectorAll('[data-test-var]').forEach(e=>p.variables.set(e.dataset.testVar,+e.value));for(const [key,n]of entries)if(n)p.bag.set(key,n);else p.bag.delete(key);if(itemText){if(quantity)p.bag.set(id,quantity);else p.bag.delete(id);}
  },'Apply test state');
 }
 async function dialogue(text,title,choice=false){return new Promise(resolve=>{let answered=false;api.modal(title,`<div class="dialogue-preview">${esc(wrapDialogue(text).replace(/\\[np]/g,'\n')).replace(/\n/g,'<br>')}</div>${choice?'<button id="scenePreviewNo" type="button">No</button>':''}`,()=>{answered=true;resolve(true);},choice?'Yes':'Continue');if(choice)$('#scenePreviewNo').onclick=()=>{answered=true;api.close();resolve(false);};$('#dialog').addEventListener('close',()=>{if(!answered)resolve(null);},{once:true});});}
 async function run(n,{standalone=false}={}){if(state.running)return;const p=api.world().state.play||state.test||{quests:new Set(),variables:new Map(),bag:new Map(),hmBadges:new Set(),hmMoves:new Set(),actorPositions:new Map(),money:0};state.test=p;p.variables??=new Map();p.quests??=new Set();p.actorPositions??=new Map();p.fieldPositions??=new Map();p.removedField??=new Set();state.running=true;state.stopped=false;state.stopType=null;if(['area','radius'].includes(n.runtime.trigger)){p.sceneInside??=new Set();p.sceneInside.add(n.id);}
  try{const issues=sceneIssues(n,api.project(),api.project().maps.find(m=>m.markers.some(v=>v.id===n.id))||api.project().maps.find(m=>m.id===state.mapId)||api.map());if(issues.length)throw Error('Finish these fields before previewing: '+issues.map(i=>i.message).join(' '));const repeat=n.runtime.repeat==='once'&&p.quests.has(n.runtime.completionFlag);if(!repeat&&!(n.runtime.conditions||[]).every(c=>conditionMet(c,api.project(),p))){await dialogue(n.runtime.failText||'Prerequisites are not met. Change Test game state to try another branch.',n.title);return;}
   await steps(repeat?n.runtime.repeatSteps:n.runtime.steps);if(!repeat&&(!state.stopped||state.stopType==='complete')){if(n.runtime.completionFlag)p.quests.add(n.runtime.completionFlag);if(n.runtime.counterId)p.variables.set(n.runtime.counterId,(p.variables.get(n.runtime.counterId)||0)+1);}
  }catch(e){api.error(e);}finally{state.running=false;api.draw();if(standalone)api.close();}
  async function steps(list){for(const s of list||[]){if(state.stopped)break;if(s.type==='say'){const value=s.dialogueId?data().dialogues.find(d=>d.id===s.dialogueId)?.text:s.text;if(await dialogue(value,n.title)===null){state.stopped=true;break;}}
    else if(s.type==='choice'){const answer=await dialogue(s.dialogueId?data().dialogues.find(d=>d.id===s.dialogueId)?.text:s.text,n.title,true);if(answer===null){state.stopped=true;break;}await steps(answer?s.yes:s.no);}
    else if(s.type==='answers'){const answer=await new Promise(resolve=>{let answered=false;api.modal(n.title,'<div class="dialogue-preview">'+esc(s.text||data().dialogues.find(d=>d.id===s.dialogueId)?.text||'')+'</div>'+s.choices.map((c,i)=>'<button type="button" data-preview-answer="'+i+'">'+esc(c.label)+'</button>').join(''),null,s.allowCancel===false?'Close preview':'Cancel');document.querySelectorAll('[data-preview-answer]').forEach(b=>b.onclick=()=>{answered=true;api.close();resolve(+b.dataset.previewAnswer);});$('#dialog').addEventListener('close',()=>{if(!answered)resolve(null);},{once:true});});if(answer===null&&s.allowCancel===false){state.stopped=true;break;}await steps(answer===null?s.cancel:s.choices[answer].steps);}
    else if(s.type==='if')await steps((s.conditions||[]).every(c=>conditionMet(c,api.project(),p))?s.then:s.else);
    else if(s.type==='flag')s.value===false?p.quests.delete(s.flagId):p.quests.add(s.flagId);
    else if(['set','add'].includes(s.type)){const v=data().variables.find(v=>v.id===s.variableId),value=s.type==='set'?+s.value:(p.variables.get(v.id)||0)+(+s.value||0);p.variables.set(v.id,Math.max(0,Math.min(2**v.bits-1,value)));}
    else if(s.type==='completeField'){completeFieldPreview(api.map().fieldObjects.find(o=>o.id===s.targetId),p);api.draw();}
    else if(s.type==='respawn'){p.healId=s.healId;api.toast('Respawn checkpoint '+s.healId+' selected for native playback.');}
    else if(s.type==='weather'){p.weather=s.weather;api.toast('Weather change: native playback in Play edited ROM.');}
    else if(s.type==='shake'){const el=document.querySelector('#canvas');if(el?.animate)await el.animate([{transform:'translate(0,0)'},{transform:`translate(${s.x}px,${s.y}px)`},{transform:`translate(${-s.x}px,${-s.y}px)`},{transform:'translate(0,0)'}],{duration:s.interval*1000/60,iterations:s.count}).finished;}
    else if(s.type==='rockfall'){if(api.map().fieldObjects?.some(o=>o.id===s.actorId))p.fieldPositions.set(s.actorId,{x:s.x,y:s.y});else p.actorPositions.set(s.actorId,{x:s.x,y:s.y,hidden:false});api.draw();api.toast('Rock landed. Native movement plays in Play edited ROM.');}
    else if(s.type==='wait')await new Promise(resolve=>setTimeout(resolve,Math.min(10000,s.frames/60*1000)));
    else if(s.type==='path'){const actor=s.actorId==='self'?n:findEvent(api.project(),s.actorId)?.n,start=s.actorId==='player'?{x:p.x??s.points[0].x,y:p.y??s.points[0].y}:p.actorPositions.get(actor.id)||{x:actor.x,y:actor.y};let pos={...start};for(const d of pathDirections(s.points)){pos={x:pos.x+DIRECTIONS[d][0],y:pos.y+DIRECTIONS[d][1],facing:d};if(s.actorId==='player')Object.assign(p,pos);else p.actorPositions.set(actor.id,pos);api.draw();await new Promise(resolve=>setTimeout(resolve,s.speed==='run'?60:120));}}
    else if(s.type==='item'){p.bag??=new Map();const id=s.itemRef||+s.itemId,have=p.bag.get(id)||0;if(s.operation==='take'&&have<s.quantity){await dialogue('Missing required item.',n.title);state.stopped=true;}else p.bag.set(id,have+(s.operation==='take'?-1:1)*(s.quantity||1));}
    else if(s.type==='money')p.money=Math.max(0,Math.min(999999,(p.money||0)+(s.operation==='take'?-1:1)*(s.amount||0)));
    else if(s.type==='visible'){const actor=s.actorId==='self'?n:findEvent(api.project(),s.actorId)?.n;if(actor)p.actorPositions.set(actor.id,{...(p.actorPositions.get(actor.id)||actor),hidden:s.visible===false});}
    else if(s.type==='face'){const actor=s.actorId==='self'?n:findEvent(api.project(),s.actorId)?.n;if(actor)p.actorPositions.set(actor.id,{...(p.actorPositions.get(actor.id)||actor),facing:s.direction});}
    else if(s.type==='warp'){if(api.world().state.play){api.loadMap(s.to.mapId,true);Object.assign(p,{mapId:s.to.mapId,x:s.to.x,y:s.to.y});}else api.toast('Preview arrival: '+s.to.x+', '+s.to.y);}
    else if(s.type==='gate'){p.openGates??=new Set();p.openGates.add(s.gateId);api.draw();}
    else if(s.type==='music'&&s.trackId)await api.music()?.previewId(s.trackId);
    else if(s.type==='stop'||s.type==='abort'){state.stopped=true;state.stopType=s.type==='stop'?'complete':'abort';break;}
    else await dialogue('Preview cue: '+SCENE_ACTIONS[s.type]+(s.emotion?' · '+s.emotion:'')+'. Use the compiled GBA player for the native effect.',n.title);
  }}
 }
 return{state,open,edit,tap,start,move,finish,draw,flow,run,testState,defaultAction};
}
